    private static void writeToFile(byte[] input, String pathname) {
        FileOutputStream outStream = null;
        try {
            outStream = new FileOutputStream(new File(pathname));
            outStream.write(input);
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            if (outStream != null) {
                try {
                    outStream.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }
